      ur: 'اس بات کا تفصیلی جائزہ کہ سعودی عرب کس طرح مصنوعی ذہانت اور خلائی تحقیق کا استعمال کرتے ہوئے تیل پر مبنی معیشت سے آگے بڑھ رہا ہے، جس میں اسٹریٹجک سرمایہ کاری اور مستقبل کے منصوبوں کی تفصیل دی گئی ہے۔'
